async (props) => {
  let arrChartPromises = [],
    arrMediaPromises = [],
    zip = new JSZip();
  return (
    this.slides.forEach((Y) => {
      arrMediaPromises = arrMediaPromises.concat(encodeSlideMediaRels(Y));
    }),
    this.slideLayouts.forEach((Y) => {
      arrMediaPromises = arrMediaPromises.concat(encodeSlideMediaRels(Y));
    }),
    (arrMediaPromises = arrMediaPromises.concat(
      encodeSlideMediaRels(this.masterSlide),
    )),
    await Promise.all(arrMediaPromises).then(async () => {
      return (
        this.slides.forEach((Y) => {
          if (Y._slideLayout) addPlaceholdersToSlideLayouts(Y);
        }),
        zip.folder("_rels"),
        zip.folder("docProps"),
        zip.folder("ppt").folder("_rels"),
        zip.folder("ppt/slideLayouts").folder("_rels"),
        zip.folder("ppt/slideMasters").folder("_rels"),
        zip.folder("ppt/slides").folder("_rels"),
        zip.folder("ppt/theme"),
        zip.folder("ppt/notesMasters").folder("_rels"),
        zip.folder("ppt/notesSlides").folder("_rels"),
        zip.file(
          "[Content_Types].xml",
          makeXmlContTypes(this.slides, this.slideLayouts, this.masterSlide),
        ),
        zip.file("_rels/.rels", makeXmlRootRels()),
        zip.file("docProps/app.xml", makeXmlApp(this.slides, this.company)),
        zip.file(
          "docProps/core.xml",
          makeXmlCore(this.title, this.subject, this.author, this.revision),
        ),
        zip.file(
          "ppt/_rels/presentation.xml.rels",
          makeXmlPresentationRels(this.slides),
        ),
        zip.file("ppt/theme/theme1.xml", makeXmlTheme(this)),
        zip.file("ppt/presentation.xml", makeXmlPresentation(this)),
        zip.file("ppt/presProps.xml", makeXmlPresProps()),
        zip.file("ppt/tableStyles.xml", makeXmlTableStyles()),
        zip.file("ppt/viewProps.xml", makeXmlViewProps()),
        this.slideLayouts.forEach((layout, idx) => {
          (zip.file(
            `ppt/slideLayouts/slideLayout${idx + 1}.xml`,
            makeXmlLayout(layout),
          ),
            zip.file(
              `ppt/slideLayouts/_rels/slideLayout${idx + 1}.xml.rels`,
              makeXmlSlideLayoutRel(idx + 1, this.slideLayouts),
            ));
        }),
        this.slides.forEach((slide, idx) => {
          (zip.file(`ppt/slides/slide${idx + 1}.xml`, makeXmlSlide(slide)),
            zip.file(
              `ppt/slides/_rels/slide${idx + 1}.xml.rels`,
              makeXmlSlideRel(this.slides, this.slideLayouts, idx + 1),
            ),
            zip.file(
              `ppt/notesSlides/notesSlide${idx + 1}.xml`,
              makeXmlNotesSlide(slide),
            ),
            zip.file(
              `ppt/notesSlides/_rels/notesSlide${idx + 1}.xml.rels`,
              makeXmlNotesSlideRel(idx + 1),
            ));
        }),
        zip.file(
          "ppt/slideMasters/slideMaster1.xml",
          makeXmlMaster(this.masterSlide, this.slideLayouts, this.theme),
        ),
        zip.file(
          "ppt/slideMasters/_rels/slideMaster1.xml.rels",
          makeXmlMasterRel(this.masterSlide, this.slideLayouts),
        ),
        zip.file("ppt/notesMasters/notesMaster1.xml", makeXmlNotesMaster()),
        zip.file(
          "ppt/notesMasters/_rels/notesMaster1.xml.rels",
          makeXmlNotesMasterRel(),
        ),
        this.slideLayouts.forEach((Y) => {
          this.createChartMediaRels(Y, zip, arrChartPromises);
        }),
        this.slides.forEach((Y) => {
          this.createChartMediaRels(Y, zip, arrChartPromises);
        }),
        this.createChartMediaRels(this.masterSlide, zip, arrChartPromises),
        await Promise.all(arrChartPromises).then(async () => {
          if (props.outputType === "STREAM")
            return await zip.generateAsync({
              type: "nodebuffer",
              compression: props.compression ? "DEFLATE" : "STORE",
            });
          else if (props.outputType)
            return await zip.generateAsync({
              type: props.outputType,
              compression: props.compression ? "DEFLATE" : "STORE",
            });
          else
            return await zip.generateAsync({
              type: "blob",
              compression: props.compression ? "DEFLATE" : "STORE",
            });
        })
      );
    })
  );
};

(function ($) {
  ((this._masterSlide._presLayout = this.presLayout),
    createSlideMaster(
      {
        objects: $,
      },
      this._masterSlide,
    ));
});

(function (props) {
  if (!props.title)
    throw Error(
      "defineSlideMaster() object argument requires a `title` value. (https://gitbrent.github.io/PptxGenJS/docs/masters.html)",
    );
  let newLayout = {
    _margin: props.margin || DEF_SLIDE_MARGIN_IN,
    _name: props.title,
    _presLayout: this.presLayout,
    _rels: [],
    _relsChart: [],
    _relsMedia: [],
    _slide: null,
    _slideNum: 1000 + this.slideLayouts.length + 1,
    _slideNumberProps: props.slideNumber || null,
    _slideObjects: [],
    _emptyPlaceholders: props.emptyPlaceholders !== !1,
    background: props.background || null,
    bkgd: props.bkgd || null,
  };
  if (
    (createSlideMaster(props, newLayout),
    this.slideLayouts.push(newLayout),
    props.background || props.bkgd)
  )
    addBackgroundDefinition(props.background, newLayout);
  if (newLayout._slideNumberProps && !this.masterSlide._slideNumberProps)
    this.masterSlide._slideNumberProps = newLayout._slideNumberProps;
});
